import struct
from PIL import Image
import numpy as np

# Let's try visualizing the data as an image in case there's a hidden picture

with open('floating_points.out', 'r') as f:
    content = f.read()

# Process the file
float_values = []
for i in range(0, len(content), 4):
    chunk = content[i:i+4]
    if len(chunk) == 4:
        try:
            val = struct.unpack('f', chunk.encode('ascii'))[0]
            float_values.append(val)
        except:
            continue

print(f'Processed {len(float_values)} float values')

# Normalize the values to 0-255 range for visualization
normalized = []
for val in float_values:
    try:
        # Simple normalization, handling extremes
        if val > 1e10 or val < -1e10 or np.isnan(val):
            normalized.append(0)
        else:
            # Use a different normalization strategy
            norm_val = (np.sin(val) + 1) * 127.5
            normalized.append(int(norm_val))
    except:
        normalized.append(0)

# Try to create an image
size = int(np.sqrt(len(normalized)))
print(f'Creating an image of size approximately {size}x{size}')

# Pad or truncate to make a square
if size * size > len(normalized):
    normalized.extend([0] * (size * size - len(normalized)))
else:
    normalized = normalized[:size * size]

# Create the image
try:
    img_array = np.array(normalized, dtype=np.uint8).reshape((size, size))
    img = Image.fromarray(img_array, 'L')  # 'L' mode for grayscale
    img.save('hidden_image.png')
    print('Image saved as hidden_image.png')
except Exception as e:
    print(f'Error creating image: {e}')

# Let's also try to see if specific values in the data might reveal something
for threshold in [0.0, 0.1, 0.5, 1.0, 10.0]:
    bits = ''
    for val in float_values:
        if abs(val) > threshold:
            bits += '1'
        else:
            bits += '0'

    # Convert to ASCII
    ascii_text = ''
    for i in range(0, len(bits), 8):
        if i + 8 <= len(bits):
            byte = bits[i:i+8]
            try:
                ascii_text += chr(int(byte, 2))
            except:
                pass

    # Check for flag
    if 'csawctf{' in ascii_text:
        start_idx = ascii_text.find('csawctf{')
        end_idx = ascii_text.find('}', start_idx)
        if end_idx > start_idx:
            print(f'Found flag with threshold {threshold}: {ascii_text[start_idx:end_idx+1]}')
            break
